_REAL_CURRENT_SEASON_TOTALS = json.loads(_REAL_CURRENT_SEASON_TOTALS_JSON)
_REAL_PRIOR_SEASON_STANDINGS = json.loads(_REAL_PRIOR_SEASON_STANDINGS_JSON)

#: 2026 (current, 2026-2027 regular season) and 2025 (prior, 2025-2026
#: regular season, completed) `seasons.id` rows -- both already existed
#: (2026) or were seeded this pass (2025, direct SQL, `seasons.league_id`
#: = the existing NFL league row) before this hook was written. Not
#: resolved dynamically here: exactly two real seasons are in play for
#: this activation, and this module is temporary, so a general
#: (league, year) -> season_id resolver was left out per this pass's
#: "smallest execution" instruction (see `team_season_stats.py`'s own
#: docstring).
_SEASON_ID_2026_CURRENT = "a2000000-0000-0000-0000-000000000003"
_SEASON_ID_2025_PRIOR = "69e16fee-8e52-4158-829e-786ebe9740e0"


class TeamSeasonStatsActivationSkipped(Exception):
    """Raised (and caught by the caller) when this pass's run_key is
    already claimed in activation_run_markers -- an overlapping/duplicate
    container boot, not an error."""


async def _claim_run_marker() -> None:
    supabase_url = os.environ["SUPABASE_URL"]
    service_role_key = os.environ["SUPABASE_SERVICE_ROLE_KEY"]
    headers = {
        "Authorization": f"Bearer {service_role_key}",
        "apikey": service_role_key,
        "Content-Type": "application/json",
    }
    async with httpx.AsyncClient(base_url=supabase_url, timeout=5.0) as client:
        response = await client.post(
            "/rest/v1/activation_run_markers",
            json={"run_key": _RUN_KEY},
            headers=headers,
        )
    if response.status_code == 409:
        raise TeamSeasonStatsActivationSkipped(
            f"run_key {_RUN_KEY!r} already claimed -- skipping duplicate activation"
        )
    if response.status_code not in (200, 201):
        raise RuntimeError(
            f"failed to claim activation_run_markers row for {_RUN_KEY!r}: "
            f"{response.status_code} {response.text}"
        )


async def run_msf_team_season_stats_activation() -> dict[str, object]:
    """Claims this pass's run_key, then runs `persist_team_season_stats`
    once per real captured season (2026 current-season totals, 2025 prior-
    season standings) against the real embedded payloads above. Returns a
    dict with each season's result, or `{"skipped": True, "reason": ...}`
    if the run_key was already claimed by another container. Zero live
    MySportsFeeds calls -- only real Supabase reads/writes."""
    try:
        await _claim_run_marker()
    except TeamSeasonStatsActivationSkipped as exc:
        return {"skipped": True, "reason": str(exc)}

    current_lines = [
        TeamSeasonStatLine(team=entry["team"]["abbreviation"], stats=entry["stats"])
        for entry in _REAL_CURRENT_SEASON_TOTALS["teamStatsTotals"]
    ]
    prior_lines = [
        TeamSeasonStatLine(team=entry["team"]["abbreviation"], stats=entry["stats"])
        for entry in _REAL_PRIOR_SEASON_STANDINGS["teams"]
    ]

    current_result = await persist_team_season_stats(
        current_lines, season_id=_SEASON_ID_2026_CURRENT, provider_name="mysportsfeeds"
    )
    prior_result = await persist_team_season_stats(
        prior_lines, season_id=_SEASON_ID_2025_PRIOR, provider_name="mysportsfeeds"
    )

    return {
        "skipped": False,
        "season_2026_current_totals": current_result.__dict__,
        "season_2025_prior_standings": prior_result.__dict__,
    }
